import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { isAbsolute, normalize } from 'node:path';
import type { CompileOptions } from '../src/backends.js';

export type SourceCostBuild = Readonly<Record<string, unknown>>;
export interface SourceCostComponent {
  readonly file: 'frontend.wasm' | 'arena.wasm';
  readonly sha256: string;
  readonly bytes: number;
}
export interface SourceCostInput {
  readonly path: string;
  readonly sha256: string;
}

export const SOURCE_COST_FROZEN_C_BANNER =
  '/* Generated by A0 a0c-0.1.62. Exact u32/bool semantics. */';

/** The archived C control permits only a compiler-version change in its first banner. */
export function verifySourceCostFrozenC(output: string, frozenSHA256: string): string {
  const banner = output.match(
    /^\/\* Generated by A0 a0c-\d+\.\d+\.\d+\. Exact u32\/bool semantics\. \*\//,
  )?.[0];
  assert.ok(banner, 'historical emitter lacks its expected version banner');
  assert.equal(
    createHash('sha256')
      .update(SOURCE_COST_FROZEN_C_BANNER + output.slice(banner.length))
      .digest('hex'),
    frozenSHA256,
    'frozen output differs beyond the recorded version banner',
  );
  return banner;
}

/** Backend comparisons always bind a separately supplied immutable compiler checkout. */
export function sourceCostControlMode(
  crossBackend: boolean,
  controlArtifact?: string,
  controlCheckout?: string,
) {
  assert.ok(!controlCheckout || controlArtifact, '--control-checkout requires --control-artifact');
  if (crossBackend) {
    assert.ok(
      controlArtifact && controlCheckout,
      '--cross-backend requires --control-artifact and --control-checkout',
    );
    return 'same-a0-source-compiled-backends';
  }
  return controlCheckout === undefined
    ? 'wasm-build-options'
    : 'same-a0-source-separate-native-transport';
}

/** Complete artifact accounting; a direct frontend also requires its generic arena module. */
export function sourceCostComponents(build: SourceCostBuild): readonly SourceCostComponent[] {
  const component = (
    file: SourceCostComponent['file'],
    digest: unknown,
    size: unknown,
  ): SourceCostComponent => {
    assert.ok(typeof digest === 'string' && /^[0-9a-f]{64}$/.test(digest), `invalid ${file} hash`);
    assert.ok(
      typeof size === 'number' && Number.isSafeInteger(size) && size > 0,
      `invalid ${file} size`,
    );
    return { file, sha256: digest, bytes: size };
  };
  if (build.backend === 'direct-wasm') {
    const components = [
      component('frontend.wasm', build.frontendSHA256, build.frontendBytes),
      component('arena.wasm', build.arenaSHA256, build.arenaBytes),
    ];
    assert.equal(
      build.totalWasmBytes,
      components.reduce((sum, item) => sum + item.bytes, 0),
      'direct total Wasm size differs',
    );
    return components;
  }
  assert.equal(build.backend, undefined, 'unsupported frontend backend');
  return [component('frontend.wasm', build.wasmSHA256, build.wasmBytes)];
}

export function sourceCostInputs(value: unknown, name: string): readonly SourceCostInput[] {
  assert.ok(Array.isArray(value), `missing ${name} inventory`);
  assert.ok(
    value.every(
      (item) =>
        item &&
        typeof item.path === 'string' &&
        item.path.length > 0 &&
        !isAbsolute(item.path) &&
        normalize(item.path) === item.path &&
        !item.path.split('/').includes('..') &&
        typeof item.sha256 === 'string' &&
        /^[0-9a-f]{64}$/.test(item.sha256),
    ),
    `invalid ${name} inventory`,
  );
  assert.equal(
    new Set(value.map((item) => item.path)).size,
    value.length,
    `duplicate ${name} inventory`,
  );
  return value as SourceCostInput[];
}

export function sourceCostModules(build: SourceCostBuild): readonly SourceCostInput[] {
  const modules =
    build.backend === 'direct-wasm'
      ? sourceCostInputs(build.inputs, 'direct input').filter((input) => input.path.endsWith('.a0'))
      : sourceCostInputs(build.modules, 'module');
  assert.ok(modules.length > 0, 'missing A0 source modules');
  return [...modules].sort((a, b) => a.path.localeCompare(b.path));
}

/** Re-emission must use recorded options, including explicit optimization and SIMD choices. */
export function sourceCostFrontendOptions(
  build: SourceCostBuild,
): CompileOptions & { readonly wasmExports: readonly string[] } {
  const value = build.frontendOptions;
  assert.ok(value && typeof value === 'object' && !Array.isArray(value), 'missing frontendOptions');
  const options = value as Record<string, unknown>;
  assert.ok(
    Object.keys(options).every((key) =>
      [
        'wasmExports',
        'wasmIo',
        'wasmSimd',
        'wasmUnroll',
        'optimize',
        'ioInputCapacity',
        'ioOutputCapacity',
      ].includes(key),
    ),
    'unsupported frontendOptions',
  );
  assert.ok(
    Array.isArray(options.wasmExports) &&
      options.wasmExports.length > 0 &&
      options.wasmExports.every((name) => typeof name === 'string' && name.length > 0),
    'invalid frontendOptions.wasmExports',
  );
  assert.equal(
    new Set(options.wasmExports).size,
    options.wasmExports.length,
    'duplicate frontendOptions.wasmExports',
  );
  for (const key of ['wasmSimd', 'optimize'])
    assert.equal(typeof options[key], 'boolean', `missing frontendOptions.${key}`);
  if (options.wasmUnroll !== undefined)
    assert.ok(
      [1, 2, 4].includes(options.wasmUnroll as number),
      'invalid frontendOptions.wasmUnroll',
    );
  for (const key of ['ioInputCapacity', 'ioOutputCapacity'])
    if (options[key] !== undefined)
      assert.ok(
        typeof options[key] === 'number' && Number.isSafeInteger(options[key]) && options[key] > 0,
        `invalid frontendOptions.${key}`,
      );
  const io = options.wasmIo as Record<string, unknown> | undefined;
  assert.ok(io && typeof io === 'object' && !Array.isArray(io), 'missing frontendOptions.wasmIo');
  assert.ok(
    Object.keys(io).every((key) => ['module', 'read', 'write', 'readPresent'].includes(key)),
    'invalid frontendOptions.wasmIo',
  );
  for (const key of ['module', 'read', 'write'])
    assert.ok(
      typeof io[key] === 'string' && io[key].length > 0,
      `invalid frontendOptions.wasmIo.${key}`,
    );
  if (io.readPresent !== undefined)
    assert.ok(
      typeof io.readPresent === 'string' && io.readPresent.length > 0,
      'invalid frontendOptions.wasmIo.readPresent',
    );
  return value as CompileOptions & { readonly wasmExports: readonly string[] };
}

function verifyCompiledBackends(candidate: SourceCostBuild, control: SourceCostBuild): void {
  assert.ok(
    (candidate.backend === 'direct-wasm') !== (control.backend === 'direct-wasm'),
    'compiled-backends control requires one direct and one C frontend',
  );
  const direct = candidate.backend === 'direct-wasm' ? candidate : control;
  const native = candidate.backend === 'direct-wasm' ? control : candidate;
  assert.equal(
    native.backend,
    undefined,
    'compiled-backends control requires the recorded C frontend',
  );
  for (const field of [
    'entry',
    'sourceSHA256',
    'frontendABI',
    'libcSHA256',
    'builtinsSHA256',
    'clang',
    'linker',
  ]) {
    assert.ok(
      Object.hasOwn(candidate, field) && candidate[field] !== undefined,
      `candidate lacks ${field}`,
    );
    assert.ok(
      Object.hasOwn(control, field) && control[field] !== undefined,
      `control lacks ${field}`,
    );
    assert.deepEqual(control[field], candidate[field], `control differs in ${field}`);
  }
  for (const field of ['sourceSHA256', 'libcSHA256', 'builtinsSHA256'])
    assert.ok(
      typeof direct[field] === 'string' && /^[0-9a-f]{64}$/.test(direct[field] as string),
      `invalid ${field}`,
    );
  for (const field of ['clang', 'linker'])
    assert.ok(
      typeof direct[field] === 'string' && (direct[field] as string).length > 0,
      `invalid ${field}`,
    );
  assert.ok(
    typeof direct.frontendABI === 'number' &&
      Number.isSafeInteger(direct.frontendABI) &&
      direct.frontendABI > 0,
    'invalid frontendABI',
  );
  assert.equal(direct.entry, 'compiler/source_frontend.a0');
  assert.ok(
    typeof direct.functionCount === 'number' &&
      Number.isInteger(direct.functionCount) &&
      direct.functionCount > 0,
    'direct function count missing',
  );
  assert.equal(direct.functionCount, native.functions, 'control differs in function count');
  assert.deepEqual(
    sourceCostModules(direct),
    sourceCostModules(native),
    'control differs in A0 module closure',
  );
  const directInputs = sourceCostInputs(direct.inputs, 'direct input');
  const nativeInputs = sourceCostInputs(native.nativeInputs, 'native input');
  for (const path of ['tools/native/arena_runtime.c', 'tools/native/arena_runtime.h']) {
    const a = directInputs.find((input) => input.path === path);
    const b = nativeInputs.find((input) => input.path === path);
    assert.ok(a && b, `missing shared ${path}`);
    assert.equal(a.sha256, b.sha256, `control differs in ${path}`);
  }
  for (const [build, fields] of [
    [native, ['aggregateBytes', 'stackBytes']],
    [direct, ['transportStackBytes']],
  ] as const)
    for (const field of fields)
      assert.ok(
        typeof build[field] === 'number' &&
          Number.isSafeInteger(build[field]) &&
          (build[field] as number) > 0,
        `unrecorded backend difference: ${field}`,
      );
  for (const [build, fields] of [
    [native, ['clangFlags', 'requiredWasmFeatures', 'symbolFlags']],
    [direct, ['requiredWasmFeatures', 'transportClangFlags', 'transportLinkerFlags']],
  ] as const)
    for (const field of fields)
      assert.ok(
        Array.isArray(build[field]) &&
          (build[field] as unknown[]).every((item) => typeof item === 'string'),
        `unrecorded backend difference: ${field}`,
      );
  for (const field of ['optimization', 'symbols'])
    assert.ok(
      typeof native[field] === 'string' && (native[field] as string).length > 0,
      `unrecorded backend difference: ${field}`,
    );
  sourceCostFrontendOptions(direct);
  assert.ok(
    direct.transportStackProof && typeof direct.transportStackProof === 'object',
    'missing transportStackProof',
  );
  sourceCostComponents(direct);
  sourceCostComponents(native);
}

/** Keep transport changes and Wasm build-option experiments in separate matched controls. */
export function verifySourceCostControl(
  candidate: SourceCostBuild,
  control: SourceCostBuild,
  transport: boolean | 'compiled-backends',
): void {
  if (transport === 'compiled-backends') {
    verifyCompiledBackends(candidate, control);
    return;
  }
  assert.equal(
    candidate.backend,
    undefined,
    'direct frontend requires compiled-backends control mode',
  );
  assert.equal(
    control.backend,
    undefined,
    'direct frontend requires compiled-backends control mode',
  );
  const fields = [
    'sourceSHA256',
    'modules',
    'frontendABI',
    'aggregateBytes',
    'stackBytes',
    'libcSHA256',
    'builtinsSHA256',
    'clang',
    'linker',
    ...(transport
      ? ['clangFlags', 'requiredWasmFeatures', 'optimization', 'symbols', 'symbolFlags']
      : ['cSHA256', 'driverSHA256', 'nativeInputs']),
  ];
  for (const field of fields) {
    assert.ok(Object.hasOwn(candidate, field), `candidate lacks ${field}`);
    assert.ok(Object.hasOwn(control, field), `control lacks ${field}`);
    assert.deepEqual(control[field], candidate[field], `control differs in ${field}`);
  }
}
